use serde::{Deserialize,Serialize}; use crate::types::cell::CellStateSave;
#[derive(Serialize,Deserialize,Default)] pub struct SaveData{ pub seeds:u32, pub potatoes:u32, pub farmer_grid_x:i32, pub farmer_grid_z:i32, pub field:Vec<Vec<CellStateSave>>, pub turrets_unlocked:bool, #[serde(default)] pub turrets_in_inventory:u32, #[serde(default)] pub turret_positions:Vec<(f32,f32,f32)>, #[serde(default)] pub iron_dome_positions:Vec<(f32,f32,f32)>, #[serde(default)] pub iron_domes_in_inventory:u32, #[serde(default)] pub blood_diamonds:u32, #[serde(default)] pub cash:u32, #[serde(default)] pub panther_statues:u32, #[serde(default)] pub gold:u32, #[serde(default)] pub bullets_count:u32, #[serde(default)] pub minigun_unlocked:bool, #[serde(default)] pub has_unlocked_blood_diamonds:bool, #[serde(default)] pub has_unlocked_cash:bool, #[serde(default)] pub has_unlocked_panther_statue:bool, #[serde(default)] pub has_unlocked_gold:bool, #[serde(default)] pub has_unlocked_bullets:bool, #[serde(default)] pub has_unlocked_minigun:bool, #[serde(default)] pub ai_slaves_count:u32, #[serde(default)] pub ai_slave_mode:u8, #[serde(default = "default_volume")] pub master_volume:f32, #[serde(default)] pub is_muted:bool }
